recommended_minimal_pattern.successful_staging:
# At successful configure commit, under fresh exact native Script selection.
# Optimization failure leaves the dedicated cache empty; it does not reject bind.
if get_script() == CinderSchedulerSporeSourceProtocol and captured_configuration is Dictionary and Exact.stringify(captured_configuration) == configuration_json:
	_configuration_reference = {"json": configuration_json, "bits": _compile_reference_bits(captured_configuration)}

recommended_minimal_pattern.selector:
func _same_configuration_reference(actual: Variant, expected_json: String) -> bool:
	if get_script() != CinderSchedulerSporeSourceProtocol:
		return Exact.stringify(actual) == expected_json
	var retained: Variant = _configuration_reference
	if not retained is Dictionary or not retained.get("json") is String or retained.json.is_empty() or retained.json != expected_json or not retained.has("bits") or typeof(retained.bits) != TYPE_DICTIONARY:
		return Exact.stringify(actual) == expected_json
	return _same_bits_reference(actual, retained.bits)
